import { fireEvent, render, screen } from '@testing-library/react';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import GuidePage from './GuidePage';
import { trackEvent, trackPageView } from '@/lib/analytics';

jest.mock('@/lib/analytics', () => ({ trackEvent: jest.fn(), trackPageView: jest.fn() }));

beforeEach(() => {
  jest.clearAllMocks();
});

test('a valid guide records its view and CTA with the known guide slug', () => {
  render(<MemoryRouter initialEntries={['/nri-parent-care?utm_source=chatgpt.com']}>
    <Routes><Route path="/:guideSlug" element={<GuidePage />} /></Routes>
  </MemoryRouter>);
  expect(screen.getByRole('heading', { name: /Stay close to parents in India/ })).toBeTruthy();
  expect(trackPageView).toHaveBeenCalledWith('guide');
  fireEvent.click(screen.getByRole('link', { name: 'Get started' }));
  expect(trackEvent).toHaveBeenCalledWith('cta_click', { id: 'guide-primary', guide: 'nri-parent-care' });
});
